-- 0011_rag_tables.sql
-- SKI RAG 七表：app_qa_item、app_synonym_custom、app_learning、app_metrics_snapshot、app_llm_usage、
-- app_response_cache、app_eval_run，兩個函式 match_qa_items、increment_search_hit_count，
-- 與 LOGIN 角色 warehouse_rag 的逐表 GRANT（KB plan ski-rag-into-vocus-warehouse S1.4）。
--
-- 背景：
--   SKI 的 RAG（QA 檢索、chat、同義詞、回饋、指標快照、LLM 記帳、回答快取、eval）目前在 Supabase。
--   子計畫裁決整套搬進本倉儲，由 rag-api（SKI api/ 轉型，S2.1）以 warehouse_rag（secret db-rag）讀寫。
--   本檔只開表、函式與權限；資料匯入在 S1.6，向量 index 在 S1.7。
--
-- 欄位來源：Supabase live DDL（2026-10-22 以 information_schema.columns＋pg_indexes＋pg_constraint 抓取，
--   KB .verification/2026-10-22/ski-rag/supabase-live-ddl.json；列數與 embedding 統計在同目錄 counts.json）。
--   以 live 為準；SKI supabase/migrations/001～012 只當註解來源（例如 learnings 的 006 寫 GENERATED ALWAYS、
--   type 註解 positive／negative，live 的 CHECK 是 feedback／miss，照 live）。
--   表名改單數 app_ 前綴（與 0009 一致），欄名、型別、預設值、NOT NULL 照 live；text 欄不加長度限制。
--   每欄 COMMENT 寫「來源 Supabase live public.<表>.<欄>」。
--
-- 與 live 的差異（刻意）：
--   - app_qa_item.id 加 CHECK 16 碼小寫 hex（live 32,439 列 id 長度皆 16、非 hex 0 列；SKI stable_id）。
--   - app_learning.id、app_llm_usage.id 是 GENERATED BY DEFAULT AS IDENTITY（live 為 identity、無 default）：
--     BY DEFAULT 讓 S1.6 匯入保留原 id，匯入後由匯入 Job `setval` 把 identity 推到 max(id)。
--   - Supabase 的 qa_items_updated_at trigger（update_updated_at()）不搬，比照 0009：本倉儲不建 trigger，
--     updated_at 由寫入端設定。increment_search_hit_count 因此不再順帶更新 updated_at。
--   - RLS 不搬（VW 無 RLS，設計盤點 R9）：讀取端每個 SELECT 自己寫 deleted_at IS NULL（只有
--     app_metrics_snapshot 有 deleted_at；live has_deleted_at 其餘六表皆 false），權限靠逐表 GRANT。
--   - search_qa_items_keyword 不搬（SKI api 無呼叫者，死碼）。FTS gin index 已在 Supabase 刪除，不建。
--   - embedding 欄在 CREATE TABLE 之後以 ALTER TABLE ADD COLUMN 加（為了測試容器逃生口，見下），
--     所以欄位順序排在最後；匯入與讀取一律寫明欄名，不依賴欄位順序。
--
-- 向量：embedding vector(1536) 可 NULL（live 94 列 NULL、其餘 32,345 列維度皆 1536）。
--   本檔**不建向量 index**。S1.7 對帳後以
--   `CREATE INDEX ... USING hnsw ((embedding::halfvec(1536)) halfvec_cosine_ops)` 建（記憶體估算見設計盤點 §4.2）。
--   match_qa_items 的排序寫成同一個表達式 `embedding::halfvec(1536) <=> query::halfvec(1536)`，索引建好後即可用上；
--   similarity 仍以全精度 `1 - (embedding <=> query)` 計算，數值與 Supabase 相同。
--   函式是 LANGUAGE sql、STABLE、非 STRICT、無 SET 子句，planner 可以 inline 進呼叫端查詢
--   （hnsw 的 ORDER BY ... LIMIT 才推得下去）；為了不依賴呼叫端 search_path，物件與運算子都寫 public. 限定。
--   Supabase 版的 `SET LOCAL ivfflat.probes = 5` 不搬（不用 IVFFlat；hnsw.ef_search 預設 40）。
--
-- 輸入上限（安全審查）：
--   match_qa_items 回傳列數夾在 1～200：`LIMIT LEAST(GREATEST(match_count, 1), 200)`（NULL、0、負數都當 1）。
--     SQL 函式不能 RAISE，夾值也不妨礙 inline；SKI 實際 top-k 遠小於 200。
--   increment_search_hit_count 的 qa_ids 超過 200 個即 RAISE（plpgsql）；NULL 或空陣列不動任何列。
--
-- 權限（逐表 GRANT，矩陣見 db/roles-matrix.md；KB plan 硬約束 1、2）：
--   warehouse_rag   SELECT 七表與 app_session；
--                   INSERT app_session、app_llm_usage、app_response_cache、app_learning、app_synonym_custom、
--                          app_metrics_snapshot；
--                   UPDATE app_qa_item 只有 (search_hit_count, freshness_score) 欄級；app_session、
--                          app_synonym_custom、app_metrics_snapshot、app_learning、app_response_cache 全欄；
--                   DELETE 只有 app_synonym_custom、app_metrics_snapshot、app_response_cache；
--                   無 TRUNCATE；兩個函式 EXECUTE（REVOKE PUBLIC 後只授 warehouse_rag）。
--   warehouse_rag 另有 app_response_cache 的 UPDATE（SKI 的 cache upsert 是 ON CONFLICT DO UPDATE，2026-10-23 裁決）。
--   warehouse_reader SELECT 六表與 app_metrics_snapshot_active view，**不給** app_metrics_snapshot 基表：
--     有 deleted_at 的表（live has_deleted_at 只有 metrics_snapshots）由 view 濾掉軟刪除列（VW 無 RLS）。
--     view 以擁有者 warehouse_admin 的權限讀基表（不設 security_invoker：invoker view 要求查詢者也有基表
--     SELECT，與「reader 不給基表」互斥），並設 security_barrier，避免查詢者的 leaky 函式在過濾前看到已刪列。
--     warehouse_rag 維持基表權限（要寫、要軟刪除）。
--   warehouse_app、warehouse_etl、warehouse_rollup 不碰。
--   identity 欄的 sequence 不需授權：INSERT 走 identity 預設值時 PostgreSQL 不檢查 sequence 權限。
--   app_qa_item 的寫入（匯入、內容更新）一律以 warehouse_admin 進行（S1.6 匯入 Job）。
--
-- 前置：
--   - warehouse_rag 由 db/roles.sql 建立（bootstrap-roles Job，需先有 Secrets Manager db-rag 容器）；
--     角色不存在時守衛中止並提示先跑 bootstrap。
--   - vector extension 由 0010 建立。不存在時中止。
-- 本檔必須以 warehouse_admin 執行（runner 預設 SET LOCAL ROLE），檔首守衛中止其他身分，所有新物件自然屬 warehouse_admin。
-- 冪等：表與 index 用 IF NOT EXISTS（PK／CHECK 寫在 CREATE TABLE 內），embedding 用 ADD COLUMN IF NOT EXISTS，
--   函式與 view CREATE OR REPLACE，COMMENT、GRANT、REVOKE 本身冪等。
--
-- 測試容器逃生口：沒有 pgvector 的一般 postgres:17 測試容器上，只有資料庫層級設定
--   `vw.allow_missing_vector = on`（同 0010）時，才略過 embedding 欄與 match_qa_items（其餘照建）。
--   正式環境沒有設定，vector extension 不存在就整檔中止。

BEGIN;

DO $do$
BEGIN
  IF current_user <> 'warehouse_admin' THEN
    RAISE EXCEPTION '0011 必須以 warehouse_admin 套用，目前 current_user 為 %', current_user;
  END IF;
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'warehouse_rag') THEN
    RAISE EXCEPTION '0011 需要角色 warehouse_rag：先以新版 db/roles.sql 跑 bootstrap-roles，再套用本檔';
  END IF;
  IF NOT EXISTS (SELECT FROM pg_extension WHERE extname = 'vector') THEN
    IF coalesce(current_setting('vw.allow_missing_vector', true), '') = 'on' THEN
      RAISE NOTICE 'pgvector 不存在且 vw.allow_missing_vector = on：略過 embedding 欄與 match_qa_items（僅限測試容器）';
    ELSE
      RAISE EXCEPTION '0011 需要 pgvector（vector extension）：先套用 0010';
    END IF;
  END IF;
END
$do$;


-- ======================================================================
-- 1. app_qa_item（← Supabase qa_items）
-- ======================================================================

CREATE TABLE IF NOT EXISTS "public"."app_qa_item" (
    "id" "text" NOT NULL,
    "seq" integer,
    "question" "text" NOT NULL,
    "answer" "text" NOT NULL,
    "keywords" "text"[] DEFAULT '{}'::"text"[],
    "confidence" real DEFAULT 0,
    "category" "text" DEFAULT ''::"text",
    "difficulty" "text" DEFAULT ''::"text",
    "evergreen" boolean DEFAULT false,
    "source_title" "text" DEFAULT ''::"text",
    "source_date" "text" DEFAULT ''::"text",
    "source_type" "text" DEFAULT 'meeting'::"text",
    "source_collection" "text" DEFAULT 'seo-meetings'::"text",
    "source_url" "text" DEFAULT ''::"text",
    "is_merged" boolean DEFAULT false,
    "extraction_model" "text",
    "synonyms" "text"[] DEFAULT '{}'::"text"[],
    "freshness_score" real DEFAULT 1.0,
    "search_hit_count" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "maturity_relevance" "text",
    "primary_category" "text",
    "categories" "text"[] DEFAULT '{}'::"text"[],
    "intent_labels" "text"[] DEFAULT '{}'::"text"[],
    "scenario_tags" "text"[] DEFAULT '{}'::"text"[],
    "serving_tier" "text" DEFAULT 'canonical'::"text",
    "retrieval_phrases" "text"[] DEFAULT '{}'::"text"[],
    "retrieval_surface_text" "text" DEFAULT ''::"text",
    "content_granularity" "text",
    "evidence_scope" "text"[] DEFAULT '{}'::"text"[],
    "booster_target_queries" "text"[] DEFAULT '{}'::"text"[],
    "hard_negative_terms" "text"[] DEFAULT '{}'::"text"[],
    CONSTRAINT "app_qa_item_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "app_qa_item_id_ck" CHECK (("id" ~ '^[0-9a-f]{16}$'::"text")),
    CONSTRAINT "app_qa_item_maturity_relevance_ck" CHECK (("maturity_relevance" = ANY (ARRAY['L1'::"text", 'L2'::"text", 'L3'::"text", 'L4'::"text"])))
);

CREATE INDEX IF NOT EXISTS "app_qa_item_category_idx" ON "public"."app_qa_item" USING "btree" ("category");
CREATE INDEX IF NOT EXISTS "app_qa_item_difficulty_idx" ON "public"."app_qa_item" USING "btree" ("difficulty");
CREATE INDEX IF NOT EXISTS "app_qa_item_evergreen_idx" ON "public"."app_qa_item" USING "btree" ("evergreen");
CREATE INDEX IF NOT EXISTS "app_qa_item_seq_idx" ON "public"."app_qa_item" USING "btree" ("seq");
CREATE INDEX IF NOT EXISTS "app_qa_item_source_collection_idx" ON "public"."app_qa_item" USING "btree" ("source_collection");
CREATE INDEX IF NOT EXISTS "app_qa_item_source_type_idx" ON "public"."app_qa_item" USING "btree" ("source_type");
CREATE INDEX IF NOT EXISTS "app_qa_item_serving_tier_idx" ON "public"."app_qa_item" USING "btree" ("serving_tier");
CREATE INDEX IF NOT EXISTS "app_qa_item_maturity_relevance_idx" ON "public"."app_qa_item" USING "btree" ("maturity_relevance") WHERE ("maturity_relevance" IS NOT NULL);
CREATE INDEX IF NOT EXISTS "app_qa_item_primary_category_idx" ON "public"."app_qa_item" USING "btree" ("primary_category") WHERE ("primary_category" IS NOT NULL);
CREATE INDEX IF NOT EXISTS "app_qa_item_categories_gin" ON "public"."app_qa_item" USING "gin" ("categories");
CREATE INDEX IF NOT EXISTS "app_qa_item_intent_labels_gin" ON "public"."app_qa_item" USING "gin" ("intent_labels");
CREATE INDEX IF NOT EXISTS "app_qa_item_scenario_tags_gin" ON "public"."app_qa_item" USING "gin" ("scenario_tags");

COMMENT ON TABLE "public"."app_qa_item" IS 'SKI RAG 的 QA 本體（KB plan ski-rag-into-vocus-warehouse S1.4）：承接 Supabase qa_items（live 32,439 列），欄位照 live DDL（KB .verification/2026-10-22/ski-rag/supabase-live-ddl.json）。寫入只經 warehouse_admin（S1.6 匯入）；warehouse_rag 只能改 search_hit_count、freshness_score。沒有 deleted_at（live 無此欄）。向量 index 由 S1.7 建（halfvec hnsw）。';

COMMENT ON COLUMN "public"."app_qa_item"."id" IS '主鍵，16 碼小寫 hex 的 stable_id（本倉儲另加 CHECK）。來源 Supabase live public.qa_items.id（text PK）；SKI supabase/migrations/001_initial_schema.sql。';
COMMENT ON COLUMN "public"."app_qa_item"."seq" IS '萃取序號。來源 Supabase live public.qa_items.seq（integer，有 btree index）。';
COMMENT ON COLUMN "public"."app_qa_item"."question" IS '問題文字（live 最長 372 bytes）。來源 Supabase live public.qa_items.question（text NOT NULL）。';
COMMENT ON COLUMN "public"."app_qa_item"."answer" IS '回答文字（live 最長 4,586 bytes）。來源 Supabase live public.qa_items.answer（text NOT NULL）。';
COMMENT ON COLUMN "public"."app_qa_item"."keywords" IS '關鍵字陣列，預設 {}。來源 Supabase live public.qa_items.keywords（text[]）。';
COMMENT ON COLUMN "public"."app_qa_item"."confidence" IS '萃取信心分數，預設 0。來源 Supabase live public.qa_items.confidence（real）。';
COMMENT ON COLUMN "public"."app_qa_item"."category" IS '分類，預設空字串（match_qa_items 的 filter_category）。來源 Supabase live public.qa_items.category（text，有 btree index）。';
COMMENT ON COLUMN "public"."app_qa_item"."difficulty" IS '難度，預設空字串。來源 Supabase live public.qa_items.difficulty（text，有 btree index）。';
COMMENT ON COLUMN "public"."app_qa_item"."evergreen" IS '是否長青內容，預設 false。來源 Supabase live public.qa_items.evergreen（boolean，有 btree index）。';
COMMENT ON COLUMN "public"."app_qa_item"."source_title" IS '來源文件標題，預設空字串。來源 Supabase live public.qa_items.source_title（text）。';
COMMENT ON COLUMN "public"."app_qa_item"."source_date" IS '來源日期字串（非 date 型別，照 live），預設空字串。來源 Supabase live public.qa_items.source_date（text）。';
COMMENT ON COLUMN "public"."app_qa_item"."source_type" IS '來源類型，預設 meeting（match_qa_items 的 filter_source_type）。來源 Supabase live public.qa_items.source_type（text，有 btree index）。';
COMMENT ON COLUMN "public"."app_qa_item"."source_collection" IS '來源集合，預設 seo-meetings（match_qa_items 的 filter_collection）。來源 Supabase live public.qa_items.source_collection（text，有 btree index）。';
COMMENT ON COLUMN "public"."app_qa_item"."source_url" IS '來源 URL，預設空字串。來源 Supabase live public.qa_items.source_url（text）。';
COMMENT ON COLUMN "public"."app_qa_item"."is_merged" IS '是否為去重合併後的列，預設 false。來源 Supabase live public.qa_items.is_merged（boolean）。';
COMMENT ON COLUMN "public"."app_qa_item"."extraction_model" IS '萃取所用模型。來源 Supabase live public.qa_items.extraction_model（text）。';
COMMENT ON COLUMN "public"."app_qa_item"."synonyms" IS '同義詞陣列，預設 {}。來源 Supabase live public.qa_items.synonyms（text[]）。';
COMMENT ON COLUMN "public"."app_qa_item"."freshness_score" IS '新鮮度分數，預設 1.0；warehouse_rag 可 UPDATE 的兩欄之一（update-freshness）。來源 Supabase live public.qa_items.freshness_score（real）。';
COMMENT ON COLUMN "public"."app_qa_item"."search_hit_count" IS '檢索命中次數，預設 0；warehouse_rag 可 UPDATE 的兩欄之一（increment_search_hit_count）。來源 Supabase live public.qa_items.search_hit_count（integer）。';
COMMENT ON COLUMN "public"."app_qa_item"."created_at" IS '列建立時刻（live 可 NULL，照搬）。來源 Supabase live public.qa_items.created_at（timestamptz DEFAULT now()）。匯入保留原值。';
COMMENT ON COLUMN "public"."app_qa_item"."updated_at" IS '最後更新時刻。來源 Supabase live public.qa_items.updated_at（timestamptz DEFAULT now()，Supabase 以 qa_items_updated_at trigger 維護）；本倉儲不建 trigger，由寫入端設定。';
COMMENT ON COLUMN "public"."app_qa_item"."maturity_relevance" IS '成熟度關聯 L1～L4（CHECK 照 live）。來源 Supabase live public.qa_items.maturity_relevance（text，partial btree index）；SKI supabase/migrations/009_maturity_relevance.sql。';
COMMENT ON COLUMN "public"."app_qa_item"."primary_category" IS '主分類。來源 Supabase live public.qa_items.primary_category（text，partial btree index）；SKI supabase/migrations/010_retrieval_metadata_columns.sql。';
COMMENT ON COLUMN "public"."app_qa_item"."categories" IS '多分類陣列，預設 {}。來源 Supabase live public.qa_items.categories（text[]，gin index）。';
COMMENT ON COLUMN "public"."app_qa_item"."intent_labels" IS '意圖標籤陣列，預設 {}。來源 Supabase live public.qa_items.intent_labels（text[]，gin index）。';
COMMENT ON COLUMN "public"."app_qa_item"."scenario_tags" IS '情境標籤陣列，預設 {}。來源 Supabase live public.qa_items.scenario_tags（text[]，gin index）。';
COMMENT ON COLUMN "public"."app_qa_item"."serving_tier" IS '服務層級，預設 canonical。來源 Supabase live public.qa_items.serving_tier（text，有 btree index）。';
COMMENT ON COLUMN "public"."app_qa_item"."retrieval_phrases" IS '檢索用短語陣列，預設 {}。來源 Supabase live public.qa_items.retrieval_phrases（text[]）。';
COMMENT ON COLUMN "public"."app_qa_item"."retrieval_surface_text" IS '檢索表層文字，預設空字串。來源 Supabase live public.qa_items.retrieval_surface_text（text）。';
COMMENT ON COLUMN "public"."app_qa_item"."content_granularity" IS '內容粒度。來源 Supabase live public.qa_items.content_granularity（text）。';
COMMENT ON COLUMN "public"."app_qa_item"."evidence_scope" IS '證據範圍陣列，預設 {}。來源 Supabase live public.qa_items.evidence_scope（text[]）。';
COMMENT ON COLUMN "public"."app_qa_item"."booster_target_queries" IS '加權目標查詢陣列，預設 {}。來源 Supabase live public.qa_items.booster_target_queries（text[]）。';
COMMENT ON COLUMN "public"."app_qa_item"."hard_negative_terms" IS '硬負例詞陣列，預設 {}。來源 Supabase live public.qa_items.hard_negative_terms（text[]）。';


-- ======================================================================
-- 2. app_synonym_custom（← Supabase synonym_custom）
-- ======================================================================

CREATE TABLE IF NOT EXISTS "public"."app_synonym_custom" (
    "term" "text" NOT NULL,
    "synonyms" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "app_synonym_custom_pkey" PRIMARY KEY ("term")
);

COMMENT ON TABLE "public"."app_synonym_custom" IS 'SKI 自訂同義詞（KB plan ski-rag-into-vocus-warehouse S1.4）：承接 Supabase synonym_custom（live 0 列），只服務 RAG 檢索展開。欄位照 live DDL（KB .verification/2026-10-22/ski-rag/supabase-live-ddl.json）。warehouse_rag 可 SELECT／INSERT／UPDATE／DELETE（Supabase 端 anon 全權 CRUD）。';

COMMENT ON COLUMN "public"."app_synonym_custom"."term" IS '主鍵，詞條。來源 Supabase live public.synonym_custom.term（text PK）。';
COMMENT ON COLUMN "public"."app_synonym_custom"."synonyms" IS '同義詞陣列，預設 {}。來源 Supabase live public.synonym_custom.synonyms（text[] NOT NULL）。';
COMMENT ON COLUMN "public"."app_synonym_custom"."created_at" IS '列建立時刻。來源 Supabase live public.synonym_custom.created_at（timestamptz NOT NULL DEFAULT now()）。';
COMMENT ON COLUMN "public"."app_synonym_custom"."updated_at" IS '最後更新時刻，由寫入端設定。來源 Supabase live public.synonym_custom.updated_at（timestamptz NOT NULL DEFAULT now()）。';


-- ======================================================================
-- 3. app_learning（← Supabase learnings）
-- ======================================================================

CREATE TABLE IF NOT EXISTS "public"."app_learning" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "type" "text" NOT NULL,
    "query" "text" NOT NULL,
    "qa_id" "text",
    "feedback" "text",
    "top_score" real,
    "context" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "app_learning_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "app_learning_type_ck" CHECK (("type" = ANY (ARRAY['feedback'::"text", 'miss'::"text"])))
);

CREATE INDEX IF NOT EXISTS "app_learning_created_at_idx" ON "public"."app_learning" USING "btree" ("created_at" DESC);
CREATE INDEX IF NOT EXISTS "app_learning_type_idx" ON "public"."app_learning" USING "btree" ("type");

COMMENT ON TABLE "public"."app_learning" IS 'SKI 檢索回饋與 miss 紀錄（KB plan ski-rag-into-vocus-warehouse S1.4）：承接 Supabase learnings（live 3 列）。欄位照 live DDL（KB .verification/2026-10-22/ski-rag/supabase-live-ddl.json）；SKI 006 的註解與 index 和 live 不同，照 live。warehouse_rag 可 SELECT／INSERT／UPDATE，無 DELETE。';

COMMENT ON COLUMN "public"."app_learning"."id" IS '主鍵 bigint identity（BY DEFAULT，匯入保留原 id，匯入後 setval 到 max(id)）。來源 Supabase live public.learnings.id（int8 NOT NULL，identity）；SKI supabase/migrations/006_learnings_table.sql 寫 GENERATED ALWAYS。';
COMMENT ON COLUMN "public"."app_learning"."type" IS '紀錄類型 feedback 或 miss（CHECK 照 live）。來源 Supabase live public.learnings.type（text NOT NULL，learnings_type_check）。';
COMMENT ON COLUMN "public"."app_learning"."query" IS '原始查詢。來源 Supabase live public.learnings.query（text NOT NULL）。';
COMMENT ON COLUMN "public"."app_learning"."qa_id" IS '關聯的 app_qa_item.id（不加外鍵，照 live）。來源 Supabase live public.learnings.qa_id（text）。';
COMMENT ON COLUMN "public"."app_learning"."feedback" IS '使用者回饋文字。來源 Supabase live public.learnings.feedback（text）。';
COMMENT ON COLUMN "public"."app_learning"."top_score" IS '回饋當下最高檢索分數。來源 Supabase live public.learnings.top_score（real）。';
COMMENT ON COLUMN "public"."app_learning"."context" IS '其他脈絡。來源 Supabase live public.learnings.context（text）。';
COMMENT ON COLUMN "public"."app_learning"."created_at" IS '列建立時刻。來源 Supabase live public.learnings.created_at（timestamptz NOT NULL DEFAULT now()）。匯入保留原值。';


-- ======================================================================
-- 4. app_metrics_snapshot（← Supabase metrics_snapshots）
-- ======================================================================

CREATE TABLE IF NOT EXISTS "public"."app_metrics_snapshot" (
    "id" "text" NOT NULL,
    "label" "text" DEFAULT ''::"text" NOT NULL,
    "source" "text" DEFAULT ''::"text" NOT NULL,
    "tab" "text" DEFAULT ''::"text" NOT NULL,
    "weeks" integer DEFAULT 1 NOT NULL,
    "metrics" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "maturity" "jsonb",
    "deleted_at" timestamp with time zone,
    CONSTRAINT "app_metrics_snapshot_pkey" PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "app_metrics_snapshot_active_idx" ON "public"."app_metrics_snapshot" USING "btree" ("created_at" DESC) WHERE ("deleted_at" IS NULL);

COMMENT ON TABLE "public"."app_metrics_snapshot" IS 'SKI 指標快照（KB plan ski-rag-into-vocus-warehouse S1.4）：承接 Supabase metrics_snapshots（live 10 列；Supabase 端沒有 CREATE，只有 011、0121 的 ALTER）。欄位照 live DDL（KB .verification/2026-10-22/ski-rag/supabase-live-ddl.json）。軟刪除：deleted_at 非 NULL 即視為已刪（Supabase 原本靠 RLS）；warehouse_reader 只能讀 app_metrics_snapshot_active，warehouse_rag 讀基表時自行加 deleted_at IS NULL。';

COMMENT ON COLUMN "public"."app_metrics_snapshot"."id" IS '主鍵（SKI 端產生的字串）。來源 Supabase live public.metrics_snapshots.id（text PK）。';
COMMENT ON COLUMN "public"."app_metrics_snapshot"."label" IS '快照標籤，預設空字串。來源 Supabase live public.metrics_snapshots.label（text NOT NULL）。';
COMMENT ON COLUMN "public"."app_metrics_snapshot"."source" IS '指標來源，預設空字串。來源 Supabase live public.metrics_snapshots.source（text NOT NULL）。';
COMMENT ON COLUMN "public"."app_metrics_snapshot"."tab" IS '前端分頁，預設空字串。來源 Supabase live public.metrics_snapshots.tab（text NOT NULL）。';
COMMENT ON COLUMN "public"."app_metrics_snapshot"."weeks" IS '涵蓋週數，預設 1。來源 Supabase live public.metrics_snapshots.weeks（integer NOT NULL）。';
COMMENT ON COLUMN "public"."app_metrics_snapshot"."metrics" IS '指標內容，預設 {}。來源 Supabase live public.metrics_snapshots.metrics（jsonb NOT NULL）。';
COMMENT ON COLUMN "public"."app_metrics_snapshot"."created_at" IS '列建立時刻。來源 Supabase live public.metrics_snapshots.created_at（timestamptz NOT NULL DEFAULT now()）。匯入保留原值。';
COMMENT ON COLUMN "public"."app_metrics_snapshot"."maturity" IS '成熟度資料。來源 Supabase live public.metrics_snapshots.maturity（jsonb）；SKI supabase/migrations/011_snapshot_maturity_column.sql。';
COMMENT ON COLUMN "public"."app_metrics_snapshot"."deleted_at" IS '軟刪除時刻；NULL 為有效列。來源 Supabase live public.metrics_snapshots.deleted_at（timestamptz）；SKI supabase/migrations/0121_soft_delete.sql。';

CREATE OR REPLACE VIEW "public"."app_metrics_snapshot_active" WITH ("security_barrier"='true') AS
 SELECT "id",
    "label",
    "source",
    "tab",
    "weeks",
    "metrics",
    "created_at",
    "maturity",
    "deleted_at"
   FROM "public"."app_metrics_snapshot"
  WHERE ("deleted_at" IS NULL);

COMMENT ON VIEW "public"."app_metrics_snapshot_active" IS '未軟刪除的指標快照（deleted_at IS NULL），warehouse_reader 唯一的讀取入口（不給基表，VW 無 RLS）。以擁有者 warehouse_admin 權限讀基表（非 security_invoker），security_barrier 防止過濾前洩漏已刪列。';


