CREATE INDEX IF NOT EXISTS "app_llm_usage_endpoint_idx" ON "public"."app_llm_usage" USING "btree" ("endpoint");

COMMENT ON TABLE "public"."app_llm_usage" IS 'SKI LLM 呼叫記帳（KB plan ski-rag-into-vocus-warehouse S1.4）：承接 Supabase llm_usage（live 0 列；Supabase 端沒有 CREATE）。欄位照 live DDL（KB .verification/2026-10-22/ski-rag/supabase-live-ddl.json）。warehouse_rag 只能 SELECT／INSERT（append-only）。';

COMMENT ON COLUMN "public"."app_llm_usage"."id" IS '主鍵 bigint identity（BY DEFAULT）。來源 Supabase live public.llm_usage.id（int8 NOT NULL，無 default，寫入端不帶 id，判定為 identity）。';
COMMENT ON COLUMN "public"."app_llm_usage"."endpoint" IS '呼叫的 API 路徑。來源 Supabase live public.llm_usage.endpoint（text NOT NULL，有 btree index）。';
COMMENT ON COLUMN "public"."app_llm_usage"."model" IS '模型名稱。來源 Supabase live public.llm_usage.model（text NOT NULL）。';
COMMENT ON COLUMN "public"."app_llm_usage"."input_tokens" IS '輸入 token 數，預設 0。來源 Supabase live public.llm_usage.input_tokens（integer NOT NULL）。';
COMMENT ON COLUMN "public"."app_llm_usage"."output_tokens" IS '輸出 token 數，預設 0。來源 Supabase live public.llm_usage.output_tokens（integer NOT NULL）。';
COMMENT ON COLUMN "public"."app_llm_usage"."latency_ms" IS '延遲毫秒，預設 0。來源 Supabase live public.llm_usage.latency_ms（integer NOT NULL）。';
COMMENT ON COLUMN "public"."app_llm_usage"."created_at" IS '列建立時刻。來源 Supabase live public.llm_usage.created_at（timestamptz NOT NULL DEFAULT now()，有 btree DESC index）。';


