COMMENT ON TABLE "public"."app_response_cache" IS 'SKI RAG 回答快取（KB plan ski-rag-into-vocus-warehouse S1.4）：承接 Supabase response_cache（live 0 列；Supabase 端沒有 CREATE），預設 TTL 2 小時。欄位照 live DDL（KB .verification/2026-10-22/ski-rag/supabase-live-ddl.json）。warehouse_rag 可 SELECT／INSERT／UPDATE／DELETE（SKI 寫入端以 query_hash upsert）。';

COMMENT ON COLUMN "public"."app_response_cache"."query_hash" IS '主鍵，正規化查詢的 sha256。來源 Supabase live public.response_cache.query_hash（text PK）。';
COMMENT ON COLUMN "public"."app_response_cache"."query_text" IS '原始查詢文字。來源 Supabase live public.response_cache.query_text（text NOT NULL）。';
COMMENT ON COLUMN "public"."app_response_cache"."response" IS '快取的回答內容。來源 Supabase live public.response_cache.response（jsonb NOT NULL）。';
COMMENT ON COLUMN "public"."app_response_cache"."created_at" IS '列建立時刻。來源 Supabase live public.response_cache.created_at（timestamptz NOT NULL DEFAULT now()）。';
COMMENT ON COLUMN "public"."app_response_cache"."expires_at" IS '過期時刻（寫入端提供，無預設）。來源 Supabase live public.response_cache.expires_at（timestamptz NOT NULL）。';
COMMENT ON COLUMN "public"."app_response_cache"."hit_count" IS '命中次數，預設 0（SKI 寫入端一律寫 0）。來源 Supabase live public.response_cache.hit_count（integer NOT NULL）。';


