-- ======================================================================
-- 8. 向量欄與 match_qa_items（需要 pgvector；測試容器逃生口見檔頭）
-- ======================================================================

DO $do$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_extension WHERE extname = 'vector') THEN
    RETURN;
  END IF;

  ALTER TABLE "public"."app_qa_item" ADD COLUMN IF NOT EXISTS "embedding" "public"."vector"(1536);

  COMMENT ON COLUMN "public"."app_qa_item"."embedding" IS 'text-embedding-3-small 的 1536 維向量（L2 正規化），可 NULL（live 94 列 NULL）。來源 Supabase live public.qa_items.embedding（vector；counts.json 維度全為 1536）；SKI supabase/migrations/001_initial_schema.sql 宣告 vector(1536)。向量 index 由 S1.7 建 hnsw ((embedding::halfvec(1536)) halfvec_cosine_ops)。';

  CREATE OR REPLACE FUNCTION "public"."match_qa_items"(
      "query_embedding" "public"."vector",
      "match_count" integer,
      "filter_category" "text" DEFAULT NULL::"text",
      "filter_source_type" "text" DEFAULT NULL::"text",
      "filter_collection" "text" DEFAULT NULL::"text")
  RETURNS TABLE("id" "text", "seq" integer, "question" "text", "answer" "text", "keywords" "text"[],
                "confidence" real, "category" "text", "difficulty" "text", "evergreen" boolean,
                "source_title" "text", "source_date" "text", "source_type" "text",
                "source_collection" "text", "source_url" "text", "is_merged" boolean,
                "extraction_model" "text", "synonyms" "text"[], "freshness_score" real,
                "search_hit_count" integer, "similarity" real)
  LANGUAGE "sql" STABLE
  AS $fn$
    SELECT qi.id, qi.seq, qi.question, qi.answer, qi.keywords, qi.confidence,
           qi.category, qi.difficulty, qi.evergreen, qi.source_title, qi.source_date,
           qi.source_type, qi.source_collection, qi.source_url, qi.is_merged,
           qi.extraction_model, qi.synonyms, qi.freshness_score, qi.search_hit_count,
           (1 - (qi.embedding OPERATOR(public.<=>) query_embedding))::real AS similarity
      FROM public.app_qa_item qi
     WHERE (filter_category IS NULL OR qi.category = filter_category)
       AND (filter_source_type IS NULL OR qi.source_type = filter_source_type)
       AND (filter_collection IS NULL OR qi.source_collection = filter_collection)
       AND qi.embedding IS NOT NULL
     ORDER BY (qi.embedding::public.halfvec(1536)) OPERATOR(public.<=>) (query_embedding::public.halfvec(1536))
     LIMIT LEAST(GREATEST(match_count, 1), 200)
  $fn$;

  COMMENT ON FUNCTION "public"."match_qa_items"("public"."vector", integer, "text", "text", "text") IS 'RAG 向量 top-k（← Supabase RPC match_qa_items，SKI supabase/migrations/008_fix_match_qa_rpc_volatile.sql；呼叫端 SKI api/src/store/supabase-qa-store.ts）。回傳欄位與 Supabase 相同；回傳列數夾在 1～200；排序用 halfvec 表達式（對齊 S1.7 的 hnsw index），similarity 用全精度 vector 計算。SECURITY INVOKER，呼叫者需 app_qa_item 的 SELECT。';

  REVOKE ALL ON FUNCTION "public"."match_qa_items"("public"."vector", integer, "text", "text", "text") FROM PUBLIC;
  GRANT EXECUTE ON FUNCTION "public"."match_qa_items"("public"."vector", integer, "text", "text", "text") TO warehouse_rag;
END
$do$;


-- ======================================================================
-- 9. increment_search_hit_count
-- ======================================================================

CREATE OR REPLACE FUNCTION "public"."increment_search_hit_count"("qa_ids" "text"[])
RETURNS void
LANGUAGE "plpgsql"
SET "search_path" TO 'pg_catalog', 'public'
AS $fn$
BEGIN
  IF cardinality(qa_ids) > 200 THEN
    RAISE EXCEPTION 'increment_search_hit_count：qa_ids 最多 200 個，收到 %', cardinality(qa_ids)
      USING ERRCODE = 'invalid_parameter_value';
  END IF;
  UPDATE public.app_qa_item
     SET search_hit_count = COALESCE(search_hit_count, 0) + 1
   WHERE id = ANY(qa_ids);
END
$fn$;

COMMENT ON FUNCTION "public"."increment_search_hit_count"("text"[]) IS '檢索命中計數 +1（← Supabase RPC increment_search_hit_count，SKI supabase/migrations/010_retrieval_metadata_columns.sql；呼叫端 SKI api/src/store/supabase-qa-store.ts）。Supabase 版是 SECURITY DEFINER；本倉儲改 SECURITY INVOKER，靠 warehouse_rag 的 search_hit_count 欄級 UPDATE，不另開提權路徑。qa_ids 最多 200 個，超過即 RAISE。不更新 updated_at（不搬 trigger）。';

REVOKE ALL ON FUNCTION "public"."increment_search_hit_count"("text"[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."increment_search_hit_count"("text"[]) TO warehouse_rag;


